export function Variant({
  label = "{{label}}",
  variant = "{{variant}}",
  accent = "{{accent}}",
  rounded = {{rounded}},
}) {
  const styles = {
    primary: { background: accent, color: "#241430", border: "none" },
    secondary: { background: "transparent", color: "#241430", border: `2px solid ${accent}` },
    ghost: { background: "transparent", color: accent, border: "none", textDecoration: "underline" },
  }[variant];
  return (
    <button type="button" style={{ font: "600 14px system-ui, sans-serif", padding: "10px 20px", borderRadius: rounded ? 999 : 8, cursor: "pointer", boxSizing: "border-box", ...styles }}>
      {label}
    </button>
  );
}
